import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.CPHNBVkq.js";const u=JSON.parse('{"title":"Tasks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tasks.md","filePath":"guide/tasks.md"}'),r={name:"guide/tasks.md"};function n(i,t,h,l,d,c){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h1><p>Tasks are things you ask Corbi to do, described in plain language. Corbi turns your description into a <strong>draft</strong> you can review before it becomes <strong>live</strong>. This gives you a chance to check the work before it runs for real.</p><blockquote><p>📷 <strong>Screenshot:</strong> <em>Task details with live and draft sections — coming soon.</em></p></blockquote><h2 id="creating-a-task" tabindex="-1">Creating a task <a class="header-anchor" href="#creating-a-task" aria-label="Permalink to &quot;Creating a task&quot;">​</a></h2><ol><li>Select <strong>Tasks</strong> in the navigation drawer.</li><li>Choose to create a new task.</li><li>In the input box (&quot;What task do you want to create?&quot;), describe the task in plain language and send it.</li></ol><p>Corbi creates the task and opens its details page.</p><div class="tip custom-block"><p class="custom-block-title">Describe the outcome, not the steps</p><p>Tell Corbi <em>what</em> you want to happen — &quot;Email me a summary of new high-priority support tickets each morning&quot; — and let it work out the steps. You&#39;ll review the result before anything goes live.</p></div><h2 id="draft-and-live-versions" tabindex="-1">Draft and live versions <a class="header-anchor" href="#draft-and-live-versions" aria-label="Permalink to &quot;Draft and live versions&quot;">​</a></h2><p>Every task has versions, and each version has a status:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Draft</strong></td><td>A proposed version you can review and refine. It isn&#39;t active yet.</td></tr><tr><td><strong>Live</strong></td><td>The version that&#39;s currently active and running.</td></tr></tbody></table><p>When you create or change a task, Corbi prepares a <strong>draft</strong>. You review the draft, and once you&#39;re happy with it, it becomes the <strong>live</strong> version. A task can have a live version, a draft, or both at once.</p><p>The task details page shows the <strong>current live version</strong> and the <strong>draft</strong> together, so you can compare what&#39;s running now with what&#39;s proposed.</p><h2 id="viewing-a-task-s-history" tabindex="-1">Viewing a task&#39;s history <a class="header-anchor" href="#viewing-a-task-s-history" aria-label="Permalink to &quot;Viewing a task&#39;s history&quot;">​</a></h2><p>From a task&#39;s details page, open the menu (the <strong>⋮</strong> icon) and choose <strong>All Versions</strong> to see every version of the task. Each entry shows its <strong>status</strong> (Draft, Live, and so on), the <strong>prompt</strong> that created it, and the date it was created. Select any version to view its details.</p><h2 id="deleting-a-task" tabindex="-1">Deleting a task <a class="header-anchor" href="#deleting-a-task" aria-label="Permalink to &quot;Deleting a task&quot;">​</a></h2><p>From a task&#39;s details page, open the <strong>⋮</strong> menu and choose <strong>Delete</strong>. You&#39;ll be asked to confirm.</p><div class="warning custom-block"><p class="custom-block-title">Deleting is permanent</p><p>Deleting a task cannot be undone. If a task is just noisy or no longer needed temporarily, consider whether you really want to remove it before confirming.</p></div><h2 id="tasks-vs-chat" tabindex="-1">Tasks vs. Chat <a class="header-anchor" href="#tasks-vs-chat" aria-label="Permalink to &quot;Tasks vs. Chat&quot;">​</a></h2><ul><li>Use <a href="./chat.html"><strong>Chat</strong></a> for a back-and-forth conversation or a one-off question.</li><li>Use <strong>Tasks</strong> when you want Corbi to carry out something structured that you can review, keep, and revisit over time.</li></ul>',19)])])}const p=e(r,[["render",n]]);export{u as __pageData,p as default};
